window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1b9149cdca204839"]={"versions": [{"id": "FIG-1b9149cdca204839", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (Struktur- und Paketdiagrammfragment).</li>\n<li><strong>Kontext & Zweck:</strong> Spezifikation von Interaktions- und Verhaltensmodellen in AUTOSAR Classic R2.1 (<code>Behavior Modeling</code>). Das Diagramm definiert die strukturelle Metamodell-Kopplung zwischen der Software-Architektur (Virtual Function Bus / SWC-Ebene) und der physikalischen Hardware-Topologie für dedizierte Sensor-/Aktor-Komponenten.</li>\n<li><strong>Architektur-Einordnung:</strong> Verankerung von <code>SensorActuatorSoftwareComponentType</code> als spezialisierte atomare SWC mit nativer Bindung an konkrete Hardware-Elemente (<code>HWElement</code>), im Kontrast zu hardwareunabhängigen Anwendungs-SWCs (<code>ApplicationSoftwareComponentType</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Components::SensorActuatorSoftwareComponentType</code>:</strong></li>\n<li>Metaklasse, spezialisiert aus der abstrakten Basisklasse <code>AtomicSoftwareComponentType</code>.</li>\n<li>Kapselt die softwareseitige Schnittstelle, Signalvorverarbeitung und Kalibrierung für spezifische Sensorik oder Aktorik auf VFB-Ebene.</li>\n<li><strong><code>Sensor Actuator::SensorActuatorHW</code>:</strong></li>\n<li>Metaklasse, spezialisiert aus <code>HWElement</code>.</li>\n<li>Repräsentiert die physikalische Hardware-Entität (elektrische/mechanische Sensor- bzw. Aktor-Hardware), die am Steuergerät angebunden ist.</li>\n<li><strong>Assoziation <code>+sensorActuator</code>:</strong></li>\n<li>Gerichtete 1:1-Assoziation: <code>Components::SensorActuatorSoftwareComponentType</code> [1] $\\rightarrow$ [1] <code>Sensor Actuator::SensorActuatorHW</code>.</li>\n<li>Jede Instanz des Software-Komponententyps referenziert exakt ein Hardware-Element; Multiplizitäten erlauben keine ungebundenen oder mehrfach assoziierten Instanzen innerhalb dieser Metamodell-Beziehung.</li>\n<li><strong>Paket <code>BM Software-Component</code> (aus <code>Behavior Modeling</code>):</strong></li>\n<li>Paketierungs-Kontext für Verhaltensmodelle von SWCs.</li>\n<li>Stereotyp <code>«import»</code>: Importiert <code>Components::SensorActuatorSoftwareComponentType</code>, um Verhaltensbeschreibungen (z. B. Internal Behavior, Runnables, Events) auf diesen Komponententyp anzuwenden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Reines Strukturmodell; kein zeitlicher oder zustandsbasierter Ablauf dargestellt.</li>\n<li><strong>Implizite System- und RTE-Dynamik:</strong></li>\n<li><strong>Design-/Konfigurationszeit:</strong> Die 1:1-Assoziation erzwingt im System-Mapping die Allokation der SWC auf diejenige ECU, welche die physikalische Verbindung zum modellierten <code>SensorActuatorHW</code> besitzt.</li>\n<li><strong>Laufzeit:</strong> Die Runnables der <code>SensorActuatorSoftwareComponentType</code> werden über RTE-Events (typischerweise zyklische <code>TimingEvent</code> oder datengetriebene <code>DataReceivedEvent</code>) getriggert und kommunizieren über standardisierte AUTOSAR-Ports (Client/Server oder Sender/Receiver) mit der Peripherie-Hardware über die darunterliegende Ecu-Abstraktionsschicht (<code>IoHwAb</code> / <code>ECU Abstraction</code>) oder Complex Device Drivers (CDD).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Allokations-Restriktion (ECU-Binding):</strong></li>\n<li>Im Gegensatz zu rein logischen <code>ApplicationSoftwareComponentType</code> ist ein <code>SensorActuatorSoftwareComponentType</code> <strong>nicht netzwerkweit frei relocierbar</strong>.</li>\n<li>Entwickler und System-Integratoren müssen sicherstellen, dass die SWC zwingend auf dem Mikrocontroller platziert wird, dessen I/O-Pins bzw. Peripherietreiber (z. B. ADC, PWM, SPI, SENT) das referenzierte <code>SensorActuatorHW</code> ansteuern.</li>\n<li><strong>Schnittstellen-Vertrag:</strong></li>\n<li>Die Anbindung an die Sensor-/Aktor-Hardware erfolgt nicht über direkte Registerzugriffe aus der SWC, sondern architekturkonform über standardisierte Port-Interfaces an die Basissoftware (typischerweise <code>IoHwAb</code> oder CDD via RTE).</li>\n<li>Port-Definitionen müssen sensorspezifische physikalische Einheiten (<code>PhysicalDimension</code>, <code>CompuMethod</code>) und Signalqualitäts-Flags bereitstellen.</li>\n<li><strong>Metamodell-Evolution (Release-Hinweis):</strong></li>\n<li>In AUTOSAR R2.1 ist die Bindung direkt im Metamodell über <code>+sensorActuator</code> modelliert.</li>\n<li>In späteren Releases (AUTOSAR 3.x/4.x Classic) wurde diese Verknüpfung verfeinert und über explizite Mapping-Beschreibungen im System-Template (<code>SwcToEcuMapping</code>, <code>SensorActuatorSwComponentType</code>) entkoppelt, wobei die normative Allokationsrestriktion auf Systemebene identisch fortbesteht.</li>\n</ul>"}, {"id": "FIG-82aebdabf46f2193", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (Struktur- und Paketdiagrammfragment).</li>\n<li><strong>Kontext & Zweck:</strong> Spezifikation von Interaktions- und Verhaltensmodellen in AUTOSAR Classic R2.1 (<code>Behavior Modeling</code>). Das Diagramm definiert die strukturelle Metamodell-Kopplung zwischen der Software-Architektur (Virtual Function Bus / SWC-Ebene) und der physikalischen Hardware-Topologie für dedizierte Sensor-/Aktor-Komponenten.</li>\n<li><strong>Architektur-Einordnung:</strong> Verankerung von <code>SensorActuatorSoftwareComponentType</code> als spezialisierte atomare SWC mit nativer Bindung an konkrete Hardware-Elemente (<code>HWElement</code>), im Kontrast zu hardwareunabhängigen Anwendungs-SWCs (<code>ApplicationSoftwareComponentType</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Components::SensorActuatorSoftwareComponentType</code>:</strong></li>\n<li>Metaklasse, spezialisiert aus der abstrakten Basisklasse <code>AtomicSoftwareComponentType</code>.</li>\n<li>Kapselt die softwareseitige Schnittstelle, Signalvorverarbeitung und Kalibrierung für spezifische Sensorik oder Aktorik auf VFB-Ebene.</li>\n<li><strong><code>Sensor Actuator::SensorActuatorHW</code>:</strong></li>\n<li>Metaklasse, spezialisiert aus <code>HWElement</code>.</li>\n<li>Repräsentiert die physikalische Hardware-Entität (elektrische/mechanische Sensor- bzw. Aktor-Hardware), die am Steuergerät angebunden ist.</li>\n<li><strong>Assoziation <code>+sensorActuator</code>:</strong></li>\n<li>Gerichtete 1:1-Assoziation: <code>Components::SensorActuatorSoftwareComponentType</code> [1] $\\rightarrow$ [1] <code>Sensor Actuator::SensorActuatorHW</code>.</li>\n<li>Jede Instanz des Software-Komponententyps referenziert exakt ein Hardware-Element; Multiplizitäten erlauben keine ungebundenen oder mehrfach assoziierten Instanzen innerhalb dieser Metamodell-Beziehung.</li>\n<li><strong>Paket <code>BM Software-Component</code> (aus <code>Behavior Modeling</code>):</strong></li>\n<li>Paketierungs-Kontext für Verhaltensmodelle von SWCs.</li>\n<li>Stereotyp <code>«import»</code>: Importiert <code>Components::SensorActuatorSoftwareComponentType</code>, um Verhaltensbeschreibungen (z. B. Internal Behavior, Runnables, Events) auf diesen Komponententyp anzuwenden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene:</strong> Reines Strukturmodell; kein zeitlicher oder zustandsbasierter Ablauf dargestellt.</li>\n<li><strong>Implizite System- und RTE-Dynamik:</strong></li>\n<li><strong>Design-/Konfigurationszeit:</strong> Die 1:1-Assoziation erzwingt im System-Mapping die Allokation der SWC auf diejenige ECU, welche die physikalische Verbindung zum modellierten <code>SensorActuatorHW</code> besitzt.</li>\n<li><strong>Laufzeit:</strong> Die Runnables der <code>SensorActuatorSoftwareComponentType</code> werden über RTE-Events (typischerweise zyklische <code>TimingEvent</code> oder datengetriebene <code>DataReceivedEvent</code>) getriggert und kommunizieren über standardisierte AUTOSAR-Ports (Client/Server oder Sender/Receiver) mit der Peripherie-Hardware über die darunterliegende Ecu-Abstraktionsschicht (<code>IoHwAb</code> / <code>ECU Abstraction</code>) oder Complex Device Drivers (CDD).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Allokations-Restriktion (ECU-Binding):</strong></li>\n<li>Im Gegensatz zu rein logischen <code>ApplicationSoftwareComponentType</code> ist ein <code>SensorActuatorSoftwareComponentType</code> <strong>nicht netzwerkweit frei relocierbar</strong>.</li>\n<li>Entwickler und System-Integratoren müssen sicherstellen, dass die SWC zwingend auf dem Mikrocontroller platziert wird, dessen I/O-Pins bzw. Peripherietreiber (z. B. ADC, PWM, SPI, SENT) das referenzierte <code>SensorActuatorHW</code> ansteuern.</li>\n<li><strong>Schnittstellen-Vertrag:</strong></li>\n<li>Die Anbindung an die Sensor-/Aktor-Hardware erfolgt nicht über direkte Registerzugriffe aus der SWC, sondern architekturkonform über standardisierte Port-Interfaces an die Basissoftware (typischerweise <code>IoHwAb</code> oder CDD via RTE).</li>\n<li>Port-Definitionen müssen sensorspezifische physikalische Einheiten (<code>PhysicalDimension</code>, <code>CompuMethod</code>) und Signalqualitäts-Flags bereitstellen.</li>\n<li><strong>Metamodell-Evolution (Release-Hinweis):</strong></li>\n<li>In AUTOSAR R2.1 ist die Bindung direkt im Metamodell über <code>+sensorActuator</code> modelliert.</li>\n<li>In späteren Releases (AUTOSAR 3.x/4.x Classic) wurde diese Verknüpfung verfeinert und über explizite Mapping-Beschreibungen im System-Template (<code>SwcToEcuMapping</code>, <code>SensorActuatorSwComponentType</code>) entkoppelt, wobei die normative Allokationsrestriktion auf Systemebene identisch fortbesteht.</li>\n</ul>"}], "trans": [{"from": "FIG-1b9149cdca204839", "to": "FIG-82aebdabf46f2193", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
